/* setjmp / longjmp for x86_64: Windows x64 ABI and System V ABI.
 * jmp_buf layout (qword indices):
 *   Windows: 0 rbx 1 rbp 2 rdi 3 rsi 4 rsp 5 r12 6 r13 7 r14 8 r15 9 rip
 *            10..11 reserved, 12..31 xmm6..xmm15 (16 bytes each)
 *   SysV   : 0 rbx 1 rbp 2 r12 3 r13 4 r14 5 r15 6 rsp 7 rip
 * longjmp does not unwind anything: it simply restores the registers. */
#if defined(__x86_64__)

#if defined(_WIN32)
__asm__(
    ".text\n"
    ".def setjmp; .scl 2; .type 32; .endef\n"
    ".globl setjmp\n"
    ".p2align 4\n"
    "setjmp:\n"
    "  mov %rbx, 0(%rcx)\n"
    "  mov %rbp, 8(%rcx)\n"
    "  mov %rdi, 16(%rcx)\n"
    "  mov %rsi, 24(%rcx)\n"
    "  lea 8(%rsp), %rax\n"
    "  mov %rax, 32(%rcx)\n"
    "  mov %r12, 40(%rcx)\n"
    "  mov %r13, 48(%rcx)\n"
    "  mov %r14, 56(%rcx)\n"
    "  mov %r15, 64(%rcx)\n"
    "  mov (%rsp), %rax\n"
    "  mov %rax, 72(%rcx)\n"
    "  movups %xmm6, 96(%rcx)\n"
    "  movups %xmm7, 112(%rcx)\n"
    "  movups %xmm8, 128(%rcx)\n"
    "  movups %xmm9, 144(%rcx)\n"
    "  movups %xmm10, 160(%rcx)\n"
    "  movups %xmm11, 176(%rcx)\n"
    "  movups %xmm12, 192(%rcx)\n"
    "  movups %xmm13, 208(%rcx)\n"
    "  movups %xmm14, 224(%rcx)\n"
    "  movups %xmm15, 240(%rcx)\n"
    "  xor %eax, %eax\n"
    "  ret\n"
    ".def longjmp; .scl 2; .type 32; .endef\n"
    ".globl longjmp\n"
    ".p2align 4\n"
    "longjmp:\n"
    "  mov %edx, %eax\n"
    "  test %eax, %eax\n"
    "  jnz 1f\n"
    "  inc %eax\n"
    "1:\n"
    "  mov 0(%rcx), %rbx\n"
    "  mov 8(%rcx), %rbp\n"
    "  mov 16(%rcx), %rdi\n"
    "  mov 24(%rcx), %rsi\n"
    "  mov 40(%rcx), %r12\n"
    "  mov 48(%rcx), %r13\n"
    "  mov 56(%rcx), %r14\n"
    "  mov 64(%rcx), %r15\n"
    "  movups 96(%rcx), %xmm6\n"
    "  movups 112(%rcx), %xmm7\n"
    "  movups 128(%rcx), %xmm8\n"
    "  movups 144(%rcx), %xmm9\n"
    "  movups 160(%rcx), %xmm10\n"
    "  movups 176(%rcx), %xmm11\n"
    "  movups 192(%rcx), %xmm12\n"
    "  movups 208(%rcx), %xmm13\n"
    "  movups 224(%rcx), %xmm14\n"
    "  movups 240(%rcx), %xmm15\n"
    "  mov 72(%rcx), %rdx\n"
    "  mov 32(%rcx), %rsp\n"
    "  jmp *%rdx\n");
#else /* System V */
__asm__(
    ".text\n"
    ".globl setjmp\n"
    ".type setjmp,@function\n"
    ".p2align 4\n"
    "setjmp:\n"
    "  mov %rbx, 0(%rdi)\n"
    "  mov %rbp, 8(%rdi)\n"
    "  mov %r12, 16(%rdi)\n"
    "  mov %r13, 24(%rdi)\n"
    "  mov %r14, 32(%rdi)\n"
    "  mov %r15, 40(%rdi)\n"
    "  lea 8(%rsp), %rax\n"
    "  mov %rax, 48(%rdi)\n"
    "  mov (%rsp), %rax\n"
    "  mov %rax, 56(%rdi)\n"
    "  xor %eax, %eax\n"
    "  ret\n"
    ".size setjmp, .-setjmp\n"
    ".globl longjmp\n"
    ".type longjmp,@function\n"
    ".p2align 4\n"
    "longjmp:\n"
    "  mov %esi, %eax\n"
    "  test %eax, %eax\n"
    "  jnz 1f\n"
    "  inc %eax\n"
    "1:\n"
    "  mov 0(%rdi), %rbx\n"
    "  mov 8(%rdi), %rbp\n"
    "  mov 16(%rdi), %r12\n"
    "  mov 24(%rdi), %r13\n"
    "  mov 32(%rdi), %r14\n"
    "  mov 40(%rdi), %r15\n"
    "  mov 56(%rdi), %rdx\n"
    "  mov 48(%rdi), %rsp\n"
    "  jmp *%rdx\n"
    ".size longjmp, .-longjmp\n");
#endif

#endif /* __x86_64__ */
